// 1. รับค่า JSON string ที่ AI ตอบกลับมา
const aiResponseText = $input.item.json.candidates[0].content.parts[0].text;
// ล้าง Markdown ออกกันเหนียว (เช่น ```json ... ```)
const cleanJson = aiResponseText.replace(/```json|```/g, '').trim();
let parsedData = {};

try {
    parsedData = JSON.parse(cleanJson);
} catch (e) {
    parsedData = { error: "Cannot parse JSON" };
}

// 2. จำลองการ Response ตามเอกสาร (Mockup)
return {
  json: {
    "type_file": "image/pdf",
    "details": [
      {
        "invoice_id": parsedData.invoice_id || null,
        "tax_id": parsedData.supplier_tax_id || null,
        "date": parsedData.date || null,
        "bill_type": "Fuel bill",
        "type": parsedData.type || "Unknown",
        "supplier_name": parsedData.supplier_name || null,
        "status": "success", // ใส่ค่าหลอกไปก่อน เพราะยังไม่ได้ต่อ DB
        "unit": parsedData.unit || 0,
        "license_plate": parsedData.license_plate || "",
        "confidence": 99 // ใส่ค่าหลอกไปก่อน
      }
    ]
  }
};

