function n(v) {
  if (v === null || v === undefined) return 0;
  if (typeof v === "number") return v;
  const s = String(v).replace(/,/g, "").trim();
  const num = Number(s);
  return Number.isFinite(num) ? num : 0;
}
function pad2(x) { return String(x).padStart(2, "0"); }

// เวลาไทย + ปี พ.ศ.
function nowThai() {
  const d = new Date();
  const tz = new Date(d.getTime() + (7 * 60 * 60 * 1000)); // UTC+7
  const yyyy = tz.getUTCFullYear() + 543;
  const mm = pad2(tz.getUTCMonth() + 1);
  const dd = pad2(tz.getUTCDate());
  const hh = pad2(tz.getUTCHours());
  const mi = pad2(tz.getUTCMinutes());
  const ss = pad2(tz.getUTCSeconds());
  return `${dd}/${mm}/${yyyy} ${hh}:${mi}:${ss}`;
}
function nowISO() {
  return new Date().toISOString();
}

// ====== CONFIG: ราคา (THB) ปรับได้ ======
const PRICE_THB_PER_1K_INPUT  = 0.0105;
const PRICE_THB_PER_1K_OUTPUT = 0.0875;

// ====== source_file ======
const source_file =
  $('Webhook_OCR_Test5').first().binary?.files0?.fileName ||
  $('Webhook_OCR_Test5').first().binary?.files?.fileName ||
  'unknown';

// ====== file_size_kb ======
const file_size_kb = Math.round(
  ($('Webhook_OCR_Test5').first().binary?.files0?.fileSize || 0) / 1024
);

// ====== caller_ip ======
const caller_ip =
  $('Code in JavaScript5').first().json.allHeaders?.['x-forwarded-for'] ||
  $('Code in JavaScript5').first().json.allHeaders?.['x-real-ip'] ||
  'unknown';

// ====== request_id ======
const request_id = `${Date.now()}-${Math.random().toString(16).slice(2)}`;
const document_id = `doc_${request_id}`;

// ====== เวลาสร้างรายการ ======
const created_at = nowThai();
const created_at_iso = nowISO();

// ====== ดึงผลลัพธ์จาก HTTP GenerateContent5 ======
const j = $json || {};

// usage tokens
const prompt_tokens     = n(j?.usageMetadata?.promptTokenCount);
const candidates_tokens = n(j?.usageMetadata?.candidatesTokenCount);
const total_tokens      = n(j?.usageMetadata?.totalTokenCount);

// model version
const model_version = j?.modelVersion || "";

// estimate cost
const est_cost_thb =
  (prompt_tokens / 1000) * PRICE_THB_PER_1K_INPUT +
  (candidates_tokens / 1000) * PRICE_THB_PER_1K_OUTPUT;

// raw text (Gemini output)
const raw_text =
  j?.candidates?.[0]?.content?.parts?.[0]?.text ||
  j?.candidates?.[0]?.content?.parts?.map(p => p.text).join("\n") ||
  "";

// raw_json (compact) + raw_text_pretty (pretty)
let raw_json = "";
let raw_text_pretty = raw_text;
let bills_count = 0;
let status = "success";
let parse_error = "";

try {
  const cleaned = String(raw_text).replace(/```json|```/g, "").trim();
  const obj = JSON.parse(cleaned);
  raw_json = JSON.stringify(obj);
  raw_text_pretty = JSON.stringify(obj, null, 2);
  bills_count = obj?.bills?.length || 0;
} catch (e) {
  raw_json = "";
  raw_text_pretty = raw_text;
  bills_count = 0;
  parse_error = String(e?.message || "parse_failed");
  status = raw_text ? "parse_error" : "error";
}

const admissionMeta = (() => { try { return $('Code (Parse Admission Result)').first().json || {}; } catch (_) { return {}; } })();

// ====== OUTPUT 1 item สำหรับ OCR_RAW ======
return [{
  json: {
    doc_type: $('Code (Build Request)').first().json.doc_type || 'unknown',
    doc_type_confidence: Number($('Code (Build Request)').first().json.doc_type_confidence || 0),
    doc_type_reason: $('Code (Build Request)').first().json.doc_type_reason || 'n/a',
    document_id,
    request_id,
    source_file,
    created_at,
    created_at_iso,
    model_version,
    prompt_tokens,
    candidates_tokens,
    total_tokens,
    est_cost_thb,
    status,
    bills_count,
    file_size_kb,
    caller_ip,
    raw_text,
    raw_text_pretty,
    raw_json,
    parse_error,
    tenant_id: String(admissionMeta.tenant_id || $('Code in JavaScript5').first().json.tenant_id || 'default'),
    admission_slot_token: String(admissionMeta.admission_slot_token || ''),
    ocr_lane: String(admissionMeta.ocr_lane || ''),
    ocr_timeout_ms: Number(admissionMeta.ocr_timeout_ms || 0),
    retry_after_sec: Number(admissionMeta.retry_after_sec || 15)
  }
}];

const items = $input.all();

function normalizeType(v) {
  const s = String(v || '').trim().toLowerCase();
  if (!s) return 'auto';
  if (['electricity','fuel','fleet_card','parking','mixed','unknown','auto'].includes(s)) return s;
  if (s === 'fleet' || s === 'fleetcard') return 'fleet_card';
  return 'auto';
}

for (const item of items) {
  const headers = item.json.headers || {};
  const body = item.json.body || {};
  const query = item.json.query || {};

  item.json.apiKey = headers['x-api-key'] || '';

  const hintedType =
    body.bill_type ||
    body.doc_type ||
    item.json.bill_type ||
    query.bill_type ||
    query.doc_type ||
    'auto';

  item.json.bill_type = normalizeType(hintedType);
}

return items;

function pad2(x) { return String(x).padStart(2, "0"); }
function nowThai() {
  const d = new Date();
  const tz = new Date(d.getTime() + (7 * 60 * 60 * 1000));
  const yyyy = tz.getUTCFullYear() + 543;
  const mm = pad2(tz.getUTCMonth() + 1);
  const dd = pad2(tz.getUTCDate());
  const hh = pad2(tz.getUTCHours());
  const mi = pad2(tz.getUTCMinutes());
  const ss = pad2(tz.getUTCSeconds());
  return `${dd}/${mm}/${yyyy} ${hh}:${mi}:${ss}`;
}

const adm = (() => { try { return $('Code (Parse Admission Result)').first().json || {}; } catch (_) { return {}; } })();
return [{
  json: {
    request_id: String(adm.request_id || `${Date.now()}-${Math.random().toString(16).slice(2)}`),
    source_file: $('Webhook_OCR_Test5').first().binary?.files0?.fileName || 'unknown',
    created_at: nowThai(),
    created_at_iso: new Date().toISOString(),
    model_version: '',
    prompt_tokens: 0,
    candidates_tokens: 0,
    total_tokens: 0,
    est_cost_thb: 0,
    status: 'error',
    bills_count: 0,
    file_size_kb: Math.round(($('Webhook_OCR_Test5').first().binary?.files0?.fileSize || 0) / 1024),
    caller_ip: $('Code in JavaScript5').first().json.allHeaders?.['x-forwarded-for'] || 'unknown',
    raw_text: JSON.stringify($json || {}),
    raw_text_pretty: '',
    raw_json: '',
    tenant_id: String(adm.tenant_id || 'default'),
    admission_slot_token: String(adm.admission_slot_token || ''),
    ocr_lane: String(adm.ocr_lane || ''),
    ocr_timeout_ms: Number(adm.ocr_timeout_ms || 0),
    retry_after_sec: Number(adm.retry_after_sec || 15)
  }
}];

const data = $('Code (Finalize Decision)').first().json;
const raw_json = data.raw_json;
const source_file = data.source_file;
const created_at = data.created_at;
const created_at_iso = data.created_at_iso;
const request_id = data.request_id;

if (!raw_json) return [];

let obj;
try {
  obj = JSON.parse(raw_json);
} catch (e) {
  return [];
}

const bills = obj?.bills || [];
const results = [];

for (const bill of bills) {
  const details = bill.list_detail || [];

  const description = details.map(d => d.description || '').join(' | ');
  const unit_price = details.map(d => d.unit_price || 0).join(' | ');
  const quantity = details.map(d => d.quantity || 0).join(' | ');
  const amount = details.map(d => d.amount || 0).join(' | ');

  // row_key = vendor_tax_id + invoice_number + invoice_date + total
  // เพื่อเช็คว่าบิลนี้เคยบันทึกแล้วหรือยัง
  const row_key = [
    bill.vendor_tax_id || '',
    bill.invoice_number || '',
    bill.invoice_date_th || '',
    bill.total || 0
  ].join('_');

  results.push({
    json: {
      vendor_tax_id: bill.vendor_tax_id || '',
      invoice_number: bill.invoice_number || '',
      invoice_date_th: bill.invoice_date_th || '',
      customer_name: bill.customer_name || '',
      address: bill.address || '',
      currency: bill.currency || 'THB',
      total: bill.total || 0,
      description,
      unit_price,
      quantity,
      amount,
      source_file,
      created_at,
      created_at_iso,
      request_id,
      row_key,
      is_duplicate: false  // จะเช็คใน step ถัดไป
    }
  });
}

return results;

// ดึง row_keys ที่มีอยู่แล้วจาก Google Sheets
const existingRows = $('Google Sheets (Get All row_key)').all();
const existingKeys = new Set(
  existingRows.map(r => r.json.row_key).filter(Boolean)
);

// ดึง bills ที่จะ insert จาก Split Bills
const newBills = $('Code (Split Bills)').all();
const results = [];

for (const bill of newBills) {
  if (existingKeys.has(bill.json.row_key)) {
    bill.json.is_duplicate = true;
  } else {
    bill.json.is_duplicate = false;
  }
  results.push(bill);
}

return results;

