parameters.jsCode:
const promptRows = $('Get row(s) in sheet1').all();
const uploadRaw = $('HTTP Upload File5').first().json || {};
function pickUploadFile(x) {
  const candidates = [
    x?.file,
    x?.body?.file,
    Array.isArray(x?.files) ? x.files[0] : null,
    Array.isArray(x?.body?.files) ? x.body.files[0] : null,
    x?.data?.file,
    x?.response?.file,
  ];
  for (const c of candidates) {
    if (c && typeof c === 'object') return c;
  }
  return {};
}
const uploadFile = pickUploadFile(uploadRaw);
const synthesizedUri = (typeof uploadFile.name === 'string' && uploadFile.name.startsWith('files/'))
  ? `https://generativelanguage.googleapis.com/v1beta/${uploadFile.name}`
  : '';
const fileData = {
  ...uploadFile,
  uri: String(uploadFile.uri || uploadFile.fileUri || synthesizedUri || ''),
  fileUri: String(uploadFile.fileUri || uploadFile.uri || synthesizedUri || ''),
  mimeType: String(uploadFile.mimeType || uploadFile.mime_type || ''),
};
if (!fileData.uri) {
  const uploadErr = String(uploadRaw?.error?.message || uploadRaw?.message || '').trim();
  throw new Error(`UPLOAD_FILE_URI_MISSING${uploadErr ? ': ' + uploadErr : ''}`);
}
const classifier = $('Code (Document Classifier)').first().json || {};
const sla = (() => { try { return $('Code (SLA Lane + Timeout Budget)').first().json || {}; } catch (_) { return {}; } })();

const docType = String(classifier.doc_type || 'unknown').toLowerCase();

const keyMap = {
  electricity: ['electricity'],
  fuel: ['fuel'],
  fleet_card: ['fleet_card'],
  parking: ['parking'],
  mixed: ['electricity', 'fuel', 'fleet_card', 'parking'],
  unknown: [],
};

const wantedTypeKeys = keyMap[docType] || [];
const selected = [];

for (const row of promptRows) {
  const active = String(row.json.active || '').toUpperCase();
  if (active !== 'TRUE') continue;

  const key = String(row.json.key || '').trim().toLowerCase();
  if (!key) continue;

  if (key === 'base') {
    selected.push(String(row.json.prompt || ''));
    continue;
  }

  if (wantedTypeKeys.includes(key)) selected.push(String(row.json.prompt || ''));
}

if (!selected.length) {
  for (const row of promptRows) {
    const active = String(row.json.active || '').toUpperCase();
    const key = String(row.json.key || '').trim().toLowerCase();
    if (active === 'TRUE' && key === 'base') {
      selected.push(String(row.json.prompt || ''));
      break;
    }
  }
}

let fewShotText = '';
let fewShotCount = 0;
try {
  const few = $('Code (Select Few-shot Examples)').first().json || {};
  fewShotText = String(few.few_shot_text || '').trim();
  fewShotCount = Number(few.few_shot_count || 0);
} catch (_) {}

const fullPrompt = selected.join('\n\n').trim();
const finalPrompt = fewShotText
  ? `${fullPrompt}\n\n### FEW-SHOT EXAMPLES (REFERENCE ONLY)\n${fewShotText}\n\nRules:\n- Use examples as reference only\n- Do not copy unrelated values\n- Return JSON only`
  : fullPrompt;

return [{
  json: {
    promptEncoded: JSON.stringify(finalPrompt),
    file: fileData,
    doc_type: docType,
    doc_type_confidence: classifier.doc_type_confidence || 0,
    doc_type_reason: classifier.doc_type_reason || 'n/a',
    few_shot_count: fewShotCount,
    ocr_lane: String(sla.ocr_lane || 'standard'),
    ocr_timeout_ms: Number(sla.ocr_timeout_ms || $env.OCR_TIMEOUT_MS || 65000),
    ocr_retry_max: Number(sla.ocr_retry_max || $env.OCR_RETRY_MAX || 2),
    retry_after_sec: Number(sla.retry_after_sec || $env.OCR_ADMISSION_RETRY_AFTER_SEC || 15),
    admission_slot_token: String(sla.admission_slot_token || classifier.admission_slot_token || ''),
    tenant_id: String(classifier.tenant_id || 'default'),
  }
}];

const items = $input.all();

function extFromName(name) {
  const s = String(name || '').toLowerCase().trim();
  const i = s.lastIndexOf('.');
  return i >= 0 ? s.slice(i + 1) : '';
}

function sniffMimeFromBase64(b64) {
  if (!b64 || typeof b64 !== 'string') return '';
  let buf;
  try { buf = Buffer.from(b64, 'base64'); } catch (_) { return ''; }
  if (!buf || buf.length < 4) return '';

  // PDF: %PDF-
  if (buf.length >= 5 && buf[0] === 0x25 && buf[1] === 0x50 && buf[2] === 0x44 && buf[3] === 0x46 && buf[4] === 0x2D) {
    return 'application/pdf';
  }

  // JPEG: FF D8 FF
  if (buf[0] === 0xFF && buf[1] === 0xD8 && buf[2] === 0xFF) {
    return 'image/jpeg';
  }

  // PNG: 89 50 4E 47 0D 0A 1A 0A
  if (
    buf.length >= 8 &&
    buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4E && buf[3] === 0x47 &&
    buf[4] === 0x0D && buf[5] === 0x0A && buf[6] === 0x1A && buf[7] === 0x0A
  ) {
    return 'image/png';
  }

  return '';
}

for (const item of items) {
  if (item.binary?.files && !item.binary?.files0) item.binary.files0 = item.binary.files;
  if (item.binary?.files_0 && !item.binary?.files0) item.binary.files0 = item.binary.files_0;
  const f = item.binary?.files0;
  if (!f) continue;

  const ext = String(f.fileExtension || '').toLowerCase() || extFromName(f.fileName);
  const mime = String(f.mimeType || '').toLowerCase();

  // Keep original if supported
  if (['application/pdf', 'image/jpeg', 'image/jpg', 'image/png'].includes(mime)) {
    if (mime === 'image/jpg') f.mimeType = 'image/jpeg';
    continue;
  }

  // Extension fallback
  if (ext === 'pdf') {
    f.mimeType = 'application/pdf';
    continue;
  }
  if (ext === 'jpg' || ext === 'jpeg') {
    f.mimeType = 'image/jpeg';
    continue;
  }
  if (ext === 'png') {
    f.mimeType = 'image/png';
    continue;
  }

  // Octet-stream or unknown: sniff file signature
  const sniffed = sniffMimeFromBase64(f.data);
  if (sniffed) {
    f.mimeType = sniffed;
  }
}

return items;

const item = $input.first();
const files = item.binary || {};
const results = [];

for (const [key, fileData] of Object.entries(files)) {
  const fileId = `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  results.push({
    json: {
      file_id: fileId,
      filename: fileData.fileName || `${fileId}.pdf`,
      mime_type: fileData.mimeType || 'application/pdf',
      status: 'pending',
      retry_count: 0,
      created_at: new Date().toISOString()
    },
    binary: {
      file: fileData
    }
  });
}

return results;

