const PRICE_THB_PER_1K_INPUT  = 0.0105;
const PRICE_THB_PER_1K_OUTPUT = 0.0875;

// ใช้ $input.item แทน $input.first()
const j = $input.item.json || {};

// file info — hardcode จาก json ที่มี หรือ empty
const source_file = j?.source_file || 'unknown';
const file_id = j?.file_id || '';

const request_id = `${Date.now()}-${Math.random().toString(16).slice(2)}`;
const created_at = nowThai();
const created_at_iso = new Date().toISOString();

const prompt_tokens     = n(j?.usageMetadata?.promptTokenCount);
const candidates_tokens = n(j?.usageMetadata?.candidatesTokenCount);
const total_tokens      = n(j?.usageMetadata?.totalTokenCount);
const model_version = j?.modelVersion || "";

const est_cost_thb =
  (prompt_tokens / 1000) * PRICE_THB_PER_1K_INPUT +
  (candidates_tokens / 1000) * PRICE_THB_PER_1K_OUTPUT;

const raw_text =
  j?.candidates?.[0]?.content?.parts?.[0]?.text || "";

let raw_json = "";
let raw_text_pretty = raw_text;
let bills_count = 0;
let status = "success";

try {
  const cleaned = String(raw_text).replace(/```json|```/g, "").trim();
  const obj = JSON.parse(cleaned);
