    source_file,
    file_id,
    created_at,
    created_at_iso,
    model_version,
    prompt_tokens,
    candidates_tokens,
    total_tokens,
    est_cost_thb,
    status,
    bills_count,
    file_size_kb: 0,
    caller_ip: 'queue-worker',
    raw_text,
    raw_text_pretty,
    raw_json
  }
};

