const promptRows = $('Get row(s) in sheet2').all();
const fileData = $('HTTP Upload File9').first().json.file || {};

let fullPrompt = '';

for (const row of promptRows) {
  const active = String(row.json.active).toUpperCase();
  if (active !== 'TRUE') continue;
  fullPrompt += row.json.prompt + '\n\n';
}

return [{
  json: {
    promptEncoded: JSON.stringify(fullPrompt.trim()),
    file: fileData
  }
}];

const items = $input.all();
for (const item of items) {
  if (item.binary?.files0) {
    item.binary.files0.mimeType = 'application/pdf';
    item.binary.files0.fileExtension = 'pdf';
  }
}
return items;

const item = $input.first();

function normalizeType(v) {
  const s = String(v || '').trim().toLowerCase();
  if (!s) return 'auto';
  if (['electricity','fuel','fleet_card','parking','mixed','unknown','auto'].includes(s)) return s;
  if (s === 'fleet' || s === 'fleetcard') return 'fleet_card';
  return 'auto';
}

const explicit = normalizeType(item.json.bill_type);
const fileName = String(item.binary?.files0?.fileName || '').toLowerCase();
let docType = 'unknown';
let confidence = 0.55;
let reason = 'fallback_unknown';

if (explicit !== 'auto' && explicit !== 'unknown') {
  docType = explicit;
  confidence = 0.99;
  reason = 'explicit_bill_type';
} else {
  if (/ค่าไฟ|electric|ab[0-9]|meter|kwh/.test(fileName)) {
    docType = 'electricity';
    confidence = 0.8;
    reason = 'filename_hint_electricity';
  } else if (/fleet|card|ระยะทาง|odometer/.test(fileName)) {
    docType = 'fleet_card';
    confidence = 0.8;
    reason = 'filename_hint_fleet_card';
  } else if (/น้ำมัน|fuel|ptt|gasohol|diesel/.test(fileName)) {
    docType = 'fuel';
    confidence = 0.78;
    reason = 'filename_hint_fuel';
  } else if (/park|parking|ที่จอด/.test(fileName)) {
    docType = 'parking';
    confidence = 0.78;
    reason = 'filename_hint_parking';
  } else {
    docType = 'unknown';
    confidence = 0.55;
    reason = 'no_hint';
  }
}

item.json.doc_type = docType;
item.json.doc_type_confidence = confidence;
item.json.doc_type_reason = reason;

return [item];

function toNum(v){ if(v===null||v===undefined||v==='') return 0; const n=Number(String(v).replace(/,/g,'').trim()); return Number.isFinite(n)?n:0; }
function toStr(v){ return v===null||v===undefined ? '' : String(v).trim(); }
function round2(n){ return Math.round((Number(n)||0)*100)/100; }
function pick(obj, keys, defVal){
  for (const k of keys) {
    if (obj && Object.prototype.hasOwnProperty.call(obj, k) && obj[k] !== undefined && obj[k] !== null && obj[k] !== '') return obj[k];
  }
  return defVal;
}
function looksNumericText(s){ return /^[-+]?\d+(\.\d+)?$/.test(String(s||'').replace(/,/g,'')); }
function inferDescription(row){
  const deny = ['vendor_tax_id','invoice_number','invoice_date_th','total','total_amount','amount','unit_price','quantity','qty','vat','sub_total','customer_tax_id'];
  for (const [k,v] of Object.entries(row||{})) {
    if (!v) continue;
    const kk = String(k||'').toLowerCase();
    if (deny.includes(kk)) continue;
    const s = toStr(v);
    if (!s) continue;
    if (looksNumericText(s)) continue;
    return s;
  }
  return '';
}
function parseFuelVolumePriceFromText(text){
  const s = String(text||'');
  if (!s) return null;
  let m = s.match(/(\d+(?:\.\d+)?)\s*L\s*[,xX\*]\s*(\d+(?:\.\d+)?)\s*(?:B\s*\/\s*L|บาท\s*\/\s*ลิตร|บ\s*\/\s*ลิตร)/i);
  if (m) return { quantity: toNum(m[1]), unit_price: toNum(m[2]) };
  m = s.match(/(\d+(?:\.\d+)?)\s*(?:B\s*\/\s*L|บาท\s*\/\s*ลิตร|บ\s*\/\s*ลิตร)\s*[,xX\*]\s*(\d+(?:\.\d+)?)\s*L/i);
  if (m) return { unit_price: toNum(m[1]), quantity: toNum(m[2]) };
  return null;
}
function isFuelFreebieOrPromoDesc(s){
  const t = String(s||'').toLowerCase();
  return /แถม|ฟรี|free|ของแถม|gift/.test(t) || (/น้ำดื่ม|water/.test(t) && /แถม|ฟรี|free|เลือก/.test(t));
}
function normalizeListDetail(rawBill){
  const arr = Array.isArray(rawBill.list_detail) ? rawBill.list_detail : (Array.isArray(rawBill.items) ? rawBill.items : []);
  const out = [];
  for (const d of arr) {
    const row = d || {};
    let description = toStr(pick(row, ['description','item_name','name','product_name','fuel_type','รายการ','รายละเอียด','สินค้า','ชนิดสินค้า','itemDescription'], ''));
    let unit_price = toNum(pick(row, ['unit_price','price_per_unit','price','ราคาต่อหน่วย','ราคาลิตร','ราคา/หน่วย'], 0));
    let quantity = toNum(pick(row, ['quantity','qty','amount_qty','จำนวน','จำนวนลิตร','ปริมาณ'], 0));
    let amount = toNum(pick(row, ['amount','total','line_total','item_total','total_amount','net_amount','รวมเงิน','จำนวนเงิน','ยอดเงิน'], 0));
    if (!description) description = inferDescription(row);

    // Parse common fuel pattern embedded in description/raw text e.g. "38.05L,15.77B/L"
    if (unit_price <= 0 || quantity <= 0) {
      const texts = [];
      if (description) texts.push(description);
      for (const v of Object.values(row)) {
        const sv = toStr(v);
        if (sv && !texts.includes(sv)) texts.push(sv);
      }
      for (const t of texts) {
        const parsed = parseFuelVolumePriceFromText(t);
        if (parsed) {
          if (quantity <= 0 && parsed.quantity > 0) quantity = parsed.quantity;
          if (unit_price <= 0 && parsed.unit_price > 0) unit_price = parsed.unit_price;
          if (!description) description = t;
          break;
        }
      }
    }

    if (amount <= 0 && unit_price > 0 && quantity > 0) amount = round2(unit_price * quantity);
    out.push({ description, unit_price, quantity, amount });
  }
  if (!out.length) out.push({ description:'', unit_price:0, quantity:0, amount:0 });
  return out;
}
function containsPromoOrDiscountText(s){
  const t = String(s||'').toLowerCase();
  return /ลด|discount|promo|promotion|แถม|free|ฟรี|เลือกรับ|เลือก/.test(t);
}
function isOrPttorFuelBill(bill){
  const tax = String(bill?.vendor_tax_id || '').replace(/\D/g,'');
  if (tax === '0107561000013') return true;
  const lines = Array.isArray(bill?.list_detail) ? bill.list_detail : [];
  return lines.some((d)=> {
    const desc = String(d?.description || '').toUpperCase();
    return desc.includes('GASOHOL') || desc.includes('PROBENZIN');
  });
}
function isManualOrHandwrittenLpgFuelBill(bill){
  const tax = String(bill?.vendor_tax_id || '').replace(/\D/g,'');
  const inv = String(bill?.invoice_number || '').replace(/\s+/g,'');
  if (!/^013555301276[06]$/.test(tax)) return false;
  if (!/^\d{6}$/.test(inv)) return false;
  const lines = Array.isArray(bill?.list_detail) ? bill.list_detail : [];
  return lines.some((d)=> /lpg|ngv|แก๊ส/i.test(String(d?.description || '')));
}
function isFuelLineMismatchException(bill){
  const lines = Array.isArray(bill?.list_detail) ? bill.list_detail : [];
  const hasPromo = lines.some((d)=> containsPromoOrDiscountText(d?.description));
  const total = round2(toNum(bill?.total));

  if (isOrPttorFuelBill(bill)) {
    if (hasPromo) return true;
    const sum = round2(lines.reduce((acc,d)=> acc + toNum(d?.amount), 0));
    if (sum > 0 && total > 0 && (sum - total) > 0.5) return true; // OR/PTTOR often has gross line amount before discount/VAT
  }

  // Generic fuel promo/freebie adjustment: exclude ancillary promo/freebie lines from line-sum reconciliation.
  if (hasPromo && total > 0) {
    const adjusted = round2(lines.reduce((acc,d)=> {
      const desc = toStr(d?.description).toLowerCase();
      const amt = round2(toNum(d?.amount));
      const isAncillary = /น้ำดื่ม|water|ของแถม|gift/.test(desc) || (isFuelFreebieOrPromoDesc(desc) && amt >= 0);
      return acc + (isAncillary ? 0 : amt);
    }, 0));
    if (Math.abs(adjusted - total) <= 1) return true;
  }

  // Generic fuel VAT-summary pattern: line item amount may be before VAT, total is after VAT (7%).
  const sum = round2(lines.reduce((acc,d)=> acc + round2(toNum(d?.amount)), 0));
  if (sum > 0 && total > 0) {
    if (isManualOrHandwrittenLpgFuelBill(bill)) {
      const delta = round2(total - sum);
      if (delta >= 0.5 && delta <= 30) return true; // handwritten OR/LPG forms often show line subtotal + VAT in footer total
    }
    const vat7Total = round2(sum * 1.07);
    if (Math.abs(vat7Total - total) <= 1) return true;
  }
  return false;
}
function applyFuelTemplateHeuristics(bill, docType){
  if (docType !== 'fuel' || !bill || !Array.isArray(bill.list_detail)) return bill;
  const tax = String(bill.vendor_tax_id || '').replace(/\D/g,'');
  const invoiceNo = String(bill.invoice_number || '').replace(/\s+/g,'');
  let fixes = Array.isArray(bill._template_fixes) ? bill._template_fixes.slice() : [];

  const tax2 = String(bill.vendor_tax_id || '').replace(/\D/g,'');
  const manualOrTaxPattern = /^013555301276[06]$/;
  const isManualOrForm = manualOrTaxPattern.test(tax2) && /^\d{6}$/.test(invoiceNo);
  if (!isManualOrForm) {
    if (fixes.length) bill._template_fixes = fixes;
    return bill;
  }
  if (tax2 !== '0135553012766') {
    bill.vendor_tax_id = '0135553012766';
    fixes.push({ code: 'manual_or_vendor_taxid_canonicalized', reason: 'ocr_digit_confusion_0_6' });
  }
  bill.list_detail = bill.list_detail.map((d, idx) => {
    const row = { ...(d || {}) };
    const desc = String(row.description || '').toLowerCase();
    const isGasLine = /lpg|ngv|แก๊ส/.test(desc);
    const up = toNum(row.unit_price);
    const qty = toNum(row.quantity);
    const amt = toNum(row.amount);
    // Template-specific heuristic: handwritten matrix form occasionally swaps qty and unit_price columns.
    // For LPG/NGV rows on this form, if unit_price > quantity and amount is substantial, prefer smaller value as unit price.
    if (isGasLine && up > 0 && qty > 0 && amt >= 300 && up > qty) {
      row.unit_price = qty;
      row.quantity = up;
      fixes.push({ code: 'swapped_unit_price_quantity', line_index: idx, reason: 'manual_or_handwritten_matrix_column_swap_heuristic' });
    }
    return row;
  });
  if (fixes.length) bill._template_fixes = fixes;
  return bill;
}
function normalizeBill(rawBill, docType){
  const b = rawBill || {};
  const normalized = {
    vendor_tax_id: toStr(pick(b, ['vendor_tax_id','vendor_taxid','tax_id'], '')),
    invoice_number: toStr(pick(b, ['invoice_number','invoice_no','receipt_no'], '')),
    invoice_date_th: toStr(pick(b, ['invoice_date_th','invoice_date','date'], '')),
    customer_name: toStr(pick(b, ['customer_name','customer','buyer_name'], '')),
    address: toStr(pick(b, ['address','customer_address'], '')),
    currency: toStr(pick(b, ['currency'], 'THB')) || 'THB',
    total: toNum(pick(b, ['total','total_amount','grand_total','ยอดรวม','รวมเงิน'], 0)),
    list_detail: normalizeListDetail(b)
  };
  if (docType === 'electricity') {
    normalized.meter_number = toStr(pick(b, ['meter_number'], ''));
    normalized.electricity_user_id = toStr(pick(b, ['electricity_user_id'], ''));
    normalized.units_used = toNum(pick(b, ['units_used'], 0));
    normalized.electricity_ref = toStr(pick(b, ['electricity_ref'], ''));
  }
  if (docType === 'fleet_card') {
    normalized.card_number = toStr(pick(b, ['card_number'], ''));
    normalized.vehicle_plate = toStr(pick(b, ['vehicle_plate'], ''));
    normalized.odometer = toStr(pick(b, ['odometer'], ''));
  }
  return normalized;
}

function normalizeInvoiceForDedupe(v){
  let s = String(v||'').toUpperCase().trim();
  s = s.replace(/[\s#\-_/\.:]/g,'');
  s = s.replace(/O/g,'0').replace(/S/g,'5');
  return s;
}
function invoiceNearEqual(a,b){
  const x = normalizeInvoiceForDedupe(a);
  const y = normalizeInvoiceForDedupe(b);
  if (!x || !y) return x === y;
  if (x === y) return true;
  if (x.endsWith(y) || y.endsWith(x)) return true; // handles leading extra digit OCR issue
  return false;
}
function canonicalLineSignature(bill){
  const arr = Array.isArray(bill?.list_detail) ? bill.list_detail : [];
  return arr.map((d)=>{
    const desc = String(d?.description||'').toUpperCase().replace(/\s+/g,' ').trim().replace(/5/g,'S');
    return [desc, round2(toNum(d?.unit_price)), round2(toNum(d?.quantity)), round2(toNum(d?.amount))].join('|');
  }).join('||');
}
function dedupeCanonicalBills(bills, docType){
  const out=[];
  for (const b of (Array.isArray(bills)?bills:[])) {
    const tax = String(b?.vendor_tax_id||'').replace(/\D/g,'');
    const date = String(b?.invoice_date_th||'').trim();
    const total = round2(toNum(b?.total));
    const inv = String(b?.invoice_number||'');
    const lineSig = canonicalLineSignature(b);
    let duplicateIdx = -1;
    for (let i=0;i<out.length;i++) {
      const o = out[i];
      const sameCore = String(o?.vendor_tax_id||'').replace(/\D/g,'')===tax && String(o?.invoice_date_th||'').trim()===date && round2(toNum(o?.total))===total;
      if (!sameCore) continue;
      const sameInv = invoiceNearEqual(o?.invoice_number, inv);
      const sameLine = canonicalLineSignature(o) === lineSig;
      if (sameInv || sameLine) { duplicateIdx = i; break; }
    }
    if (duplicateIdx === -1) {
      out.push(b);
      continue;
    }
    const score = (x)=>{
      let s=0;
      if (String(x?.vendor_tax_id||'').replace(/\D/g,'').length===13) s+=5;
      if (String(x?.invoice_number||'').trim()) s+=3;
      if (String(x?.invoice_date_th||'').trim()) s+=2;
      if (round2(toNum(x?.total))>0) s+=2;
      for (const d of (x?.list_detail||[])) {
        if (toNum(d?.amount)>0) s+=1;
        if (String(d?.description||'').trim()) s+=1;
      }
      // prefer invoice numbers that contain Thai/alpha prefixes or # less? penalize pure long digit OCR variant slightly
      const invN = normalizeInvoiceForDedupe(x?.invoice_number||'');
      if (/^\d{12,20}$/.test(invN)) s-=0.5;
      return s;
    };
    if (score(b) > score(out[duplicateIdx])) out[duplicateIdx] = b;
  }
  return out;
}
function inferDocTypeFromCanonicalBills(currentDocType, bills){
  const t = String(currentDocType||'unknown').toLowerCase();
  if (t && t !== 'unknown' && t !== 'auto') return { doc_type: t, changed:false, reason: '' };
  const all = Array.isArray(bills)?bills:[];
  const fuelKeywords = ['gasohol','diesel','benzin','lpg','ngv','p-diesel','fuelsave','e20','g95','g91','แก๊ส','น้ำมัน','ดีเซล'];
  const fuelTaxIds = new Set(['0105555130588','0105564172883','0107536000064','0105536080112','0115555015410','0305563000017','0105535056684','0107548000650','0135552006240','0107561000013','0135553012766']);
  for (const b of all) {
    const tax = String(b?.vendor_tax_id||'').replace(/\D/g,'');
    const lines = Array.isArray(b?.list_detail)?b.list_detail:[];
    const text = [tax, String(b?.invoice_number||''), ...lines.map(d=>String(d?.description||''))].join(' ').toLowerCase();
    const hasFuelWord = fuelKeywords.some(k => text.includes(k));
    const hasFuelTax = fuelTaxIds.has(tax);
    if (hasFuelWord || hasFuelTax) return { doc_type:'fuel', changed:true, reason:'content_hint_fuel' };
  }
  return { doc_type: t || 'unknown', changed:false, reason:'' };
}

function validateBill(bill, docType){
  const errs=[];
  const date=String(bill.invoice_date_th||'');
  const tax=String(bill.vendor_tax_id||'');
  const inv=String(bill.invoice_number||'');
  const total=toNum(bill.total);
  if(!date || !/^\d{2}\/\d{2}\/\d{4}$/.test(date)) errs.push({field:'invoice_date_th',severity:'critical',code:'invalid_date_format'});
  if(!inv) errs.push({field:'invoice_number',severity:'critical',code:'missing_invoice_number'});
  if(!(total>=0)) errs.push({field:'total',severity:'critical',code:'invalid_total'});
  if(tax && !/^0\d{12}$/.test(tax.replace(/\D/g,''))) errs.push({field:'vendor_tax_id',severity:'critical',code:'invalid_vendor_tax_id'});
  if(Array.isArray(bill.list_detail)){
    bill.list_detail.forEach((d,idx)=>{
      const _descLine = toStr(d.description).toLowerCase();
      const _isFreebieLine = isFuelFreebieOrPromoDesc(_descLine) && toNum(d.amount) <= 0;
      if((toNum(d.quantity)>0 || toNum(d.unit_price)>0) && toNum(d.amount)<=0 && !_isFreebieLine) errs.push({field:`list_detail[${idx}].amount`,severity:'warning',code:'line_amount_missing'});
      if((toNum(d.quantity)>0 || toNum(d.unit_price)>0) && !toStr(d.description)) errs.push({field:`list_detail[${idx}].description`,severity:'warning',code:'line_description_missing'});
      const q = toNum(d.quantity), up = toNum(d.unit_price), amt = toNum(d.amount);
      const desc = toStr(d.description).toLowerCase();
      if (q > 0 && up > 0 && amt > 0) {
        const calc = round2(q * up);
        const diff = Math.abs(calc - round2(amt));
        const hasPromo = containsPromoOrDiscountText(desc);
        const isManualLpg = docType === 'fuel' && isManualOrHandwrittenLpgFuelBill(bill);
        const arithmeticTolerance = isManualLpg ? 5 : 1;
        if (!hasPromo && diff > arithmeticTolerance) {
          errs.push({field:`list_detail[${idx}]`,severity:'warning',code:'line_arithmetic_mismatch',details:{calc_amount:calc,amount:round2(amt),diff}});
        }
      }
    });
    if(docType==='fuel'){
      const lineSum = round2(bill.list_detail.reduce((acc,d)=> acc + toNum(d?.amount), 0));
      const totalRounded = round2(total);
      const hasPositiveLine = bill.list_detail.some((d)=>toNum(d?.amount)>0);
      const hasAnyDesc = bill.list_detail.some((d)=>toStr(d?.description));
      if (!hasPositiveLine && totalRounded > 0) {
        errs.push({field:'list_detail',severity:'warning',code:'fuel_missing_line_items',details:{total:totalRounded,has_any_description:hasAnyDesc}});
      }
      if (hasPositiveLine && totalRounded > 0 && Math.abs(lineSum - totalRounded) > 0.5) {
        if (!isFuelLineMismatchException(bill)) {
          errs.push({field:'list_detail',severity:'warning',code:'fuel_line_total_mismatch',details:{line_sum:lineSum,total:totalRounded}});
        }
      }
    }
  }
  if(docType==='electricity'){
    const meter=String(bill.meter_number||''); const ref=String(bill.electricity_ref||'');
    if(meter && !/^\d{10}$/.test(meter)) errs.push({field:'meter_number',severity:'critical',code:'invalid_meter_number'});
    if(ref && !/^\d{12}$/.test(ref)) errs.push({field:'electricity_ref',severity:'critical',code:'invalid_electricity_ref'});
    if(inv && !/^AB/i.test(inv)) errs.push({field:'invoice_number',severity:'critical',code:'electricity_invoice_should_start_ab'});
  }
  if(docType==='fleet_card'){
    const odo=String(bill.odometer||'');
    if(odo && !/^\d{3,9}$/.test(odo)) errs.push({field:'odometer',severity:'critical',code:'invalid_odometer'});
  }
  return errs;
}

