function diff(a, b, p, out){
  if (Array.isArray(a) || Array.isArray(b)) {
    const aa = Array.isArray(a) ? a : [];
    const bb = Array.isArray(b) ? b : [];
    const n = Math.max(aa.length, bb.length);
    for (let i=0;i<n;i++) diff(aa[i], bb[i], `${p}[${i}]`, out);
    return;
  }
  if (isObj(a) || isObj(b)) {
    const ao = isObj(a) ? a : {};
    const bo = isObj(b) ? b : {};
    const ks = Array.from(new Set([...Object.keys(ao), ...Object.keys(bo)])).sort();
    for (const k of ks) diff(ao[k], bo[k], p ? `${p}.${k}` : k, out);
    return;
  }
  const av = a === undefined ? null : a;
  const bv = b === undefined ? null : b;
  if (JSON.stringify(av) !== JSON.stringify(bv)) {
    out.push({ field_path: p || '$', from: av, to: bv });
  }
}

