return [{ json: { ...src.json, tenant_id: tenantId, request_id: requestId, admission_payload: { action: 'acquire_slot', tenant_id: tenantId, request_id: requestId, global_limit: Number($env.OCR_ADMISSION_GLOBAL_LIMIT || 8), tenant_limit: Number($env.OCR_ADMISSION_TENANT_LIMIT || 4), ttl_sec: Number($env.OCR_ADMISSION_LEASE_TTL_SEC || 180), retry_after_sec: retryAfter } }, binary: src.binary }];

const src = $('Code (Build Admission Acquire Payload)').first();
const resp = $json || {};
const data = (resp && typeof resp === 'object' && resp.data && typeof resp.data === 'object') ? resp.data : {};
const fallbackRetry = Number($env.OCR_ADMISSION_RETRY_AFTER_SEC || 15);
let allowed = false;
let response_code = 503;
let error_code = 'SYSTEM_BUSY';
let message = 'OCR queue is busy. Please retry.';
let retry_after_sec = Number(data.retry_after_sec || fallbackRetry);
let slotToken = '';

if (Object.keys(data).length === 0) {
  response_code = 503;
  error_code = 'ADMISSION_SERVICE_UNAVAILABLE';
  message = 'Admission service unavailable';
} else if (data.allowed === true) {
  allowed = true;
  response_code = 200;
  error_code = '';
  message = 'OK';
  slotToken = String(data.slot_token || '');
} else {
  response_code = Number(data.code || 429);
  error_code = String(data.reason || 'SYSTEM_BUSY');
  message = 'OCR queue is busy. Please retry.';
}

return [{ json: { ...src.json, allowed, response_code, error_code, message, retry_after_sec, admission_slot_token: slotToken }, binary: src.binary }];

const item = $input.first();
const j = item.json || {};
const fileSizeKb = Math.round((item.binary?.files0?.fileSize || 0) / 1024);
const docType = String(j.doc_type || 'unknown').toLowerCase();
let lane = 'standard';
if (fileSizeKb >= 4000 || docType === 'mixed') lane = 'heavy';
else if (fileSizeKb <= 700 && ['fuel','parking'].includes(docType)) lane = 'fast';
const timeoutByLane = { fast: Number($env.OCR_TIMEOUT_FAST_MS || 45000), standard: Number($env.OCR_TIMEOUT_STANDARD_MS || 65000), heavy: Number($env.OCR_TIMEOUT_HEAVY_MS || 90000) };
const retryByLane = { fast: 1, standard: 2, heavy: 2 };
return [{ json: { ...j, ocr_lane: lane, ocr_timeout_ms: Number(timeoutByLane[lane] || 65000), ocr_retry_max: Number(retryByLane[lane] || 2), retry_after_sec: Number(j.retry_after_sec || $env.OCR_ADMISSION_RETRY_AFTER_SEC || 15), admission_slot_token: String(j.admission_slot_token || '') }, binary: item.binary }];
